//! Routing between [`Service`]s and handlers.

use self::{future::RouterFuture, not_found::NotFound};
use crate::{
    body::{boxed, Body, Bytes, HttpBody},
    extract::{
        connect_info::{Connected, IntoMakeServiceWithConnectInfo},
        MatchedPath, OriginalUri,
    },
    response::Response,
    routing::strip_prefix::StripPrefix,
    util::{try_downcast, ByteStr, PercentDecodedByteStr},
    BoxError,
};
use http::{Request, StatusCode, Uri};
use std::{
    borrow::Cow,
    collections::HashMap,
    convert::Infallible,
    fmt,
    sync::Arc,
    task::{Context, Poll},
};
use tower::{layer::layer_fn, ServiceBuilder};
use tower_http::map_response_body::MapResponseBodyLayer;
use tower_layer::Layer;
use tower_service::Service;

pub mod future;

mod into_make_service;
mod method_filter;
mod method_routing;
mod not_found;
mod route;
mod strip_prefix;

#[cfg(test)]
mod tests;

pub use self::{into_make_service::IntoMakeService, method_filter::MethodFilter, route::Route};

pub use self::method_routing::{
    any, any_service, delete, delete_service, get, get_service, head, head_service, on, on_service,
    options, options_service, patch, patch_service, post, post_service, put, put_service, trace,
    trace_service, MethodRouter,
};

#[derive(Clone, Copy, Debug, PartialEq, Eq, PartialOrd, Ord, Hash)]
struct RouteId(u32);

impl RouteId {
    fn next() -> Self {
        use std::sync::atomic::{AtomicU32, Ordering};
        // `AtomicU64` isn't supported on all platforms
        static ID: AtomicU32 = AtomicU32::new(0);
        let id = ID.fetch_add(1, Ordering::Relaxed);
        if id == u32::MAX {
            panic!("Over `u32::MAX` routes created. If you need this, please file an issue.");
        }
        Self(id)
    }
}

/// The router type for composing handlers and services.
#[derive(Debug)]
pub struct Router<B = Body> {
    routes: HashMap<RouteId, Endpoint<B>>,
    node: Node,
    fallback: Fallback<B>,
    nested_at_root: bool,
}

impl<B> Clone for Router<B> {
    fn clone(&self) -> Self {
        Self {
            routes: self.routes.clone(),
            node: self.node.clone(),
            fallback: self.fallback.clone(),
            nested_at_root: self.nested_at_root,
        }
    }
}

impl<B> Default for Router<B>
where
    B: Send + 'static,
{
    fn default() -> Self {
        Self::new()
    }
}

pub(crate) const NEST_TAIL_PARAM: &str = "axum_nest";
const NEST_TAIL_PARAM_CAPTURE: &str = "/*axum_nest";

impl<B> Router<B>
where
    B: Send + 'static,
{
    /// Create a new `Router`.
    ///
    /// Unless you add additional routes this will respond with `404 Not Found` to
    /// all requests.
    pub fn new() -> Self {
        Self {
            routes: Default::default(),
            node: Default::default(),
            fallback: Fallback::Default(Route::new(NotFound)),
            nested_at_root: false,
        }
    }

    #[doc = include_str!("../docs/routing/route.md")]
    pub fn route<T>(mut self, path: &str, service: T) -> Self
    where
        T: Service<Request<B>, Response = Response, Error = Infallible> + Clone + Send + 'static,
        T::Future: Send + 'static,
    {
        if path.is_empty() {
            panic!("Invalid route: empty path");
        }

        let service = match try_downcast::<Router<B>, _>(service) {
            Ok(_) => {
                panic!("Invalid route: `Router::route` cannot be used with `Router`s. Use `Router::nest` instead")
            }
            Err(svc) => svc,
        };

        let id = RouteId::next();

        let service = match try_downcast::<MethodRouter<B, Infallible>, _>(service) {
            Ok(method_router) => {
                if let Some((route_id, Endpoint::MethodRouter(prev_method_router))) = self
                    .node
                    .path_to_route_id
                    .get(path)
                    .and_then(|route_id| self.routes.get(route_id).map(|svc| (*route_id, svc)))
                {
                    // if we're adding a new `MethodRouter` to a route that already has one just
                    // merge them. This makes `.route("/", get(_)).route("/", post(_))` work
                    let service =
                        Endpoint::MethodRouter(prev_method_router.clone().merge(method_router));
                    self.routes.insert(route_id, service);
                    return self;
                } else {
                    Endpoint::MethodRouter(method_router)
                }
            }
            Err(service) => Endpoint::Route(Route::new(service)),
        };

        if let Err(err) = self.node.insert(path, id) {
            self.panic_on_matchit_error(err);
        }

        self.routes.insert(id, service);

        self
    }

    #[doc = include_str!("../docs/routing/nest.md")]
    pub fn nest<T>(mut self, path: &str, svc: T) -> Self
    where
        T: Service<Request<B>, Response = Response, Error = Infallible> + Clone + Send + 'static,
        T::Future: Send + 'static,
    {
        if path.is_empty() {
            panic!("Invalid route: empty path");
        }

        let path_bytes = path.as_bytes();
        let mut offset = 0;
        let mut has_wildcard = false;
        while offset < path_bytes.len() {
            if path_bytes[offset] == b'*' {
                has_wildcard = true;
                break;
            } else {
                offset += 1;
            }
        }
        if has_wildcard {
            panic!("Invalid route: nested routes cannot contain wildcards (*)");
        }

        if path == "/" {
            self.nested_at_root = true;
        }

        let prefix_bytes = ByteStr::new(path);
        let prefix = prefix_bytes.as_str();

        let mut svc_holder = Some(svc);
        if let Some(router_slot) =
            <dyn std::any::Any>::downcast_mut::<Option<Router<B>>>(&mut svc_holder)
        {
            let router = router_slot.take().unwrap();
            let Router {
                mut routes,
                node,
                fallback,
                nested_at_root: _,
            } = router;

            if let Fallback::Custom(_) = fallback {
                panic!("Cannot nest `Router`s that has a fallback");
            }

            for (id, nested_path) in node.route_id_to_path {
                let route = routes.remove(&id).unwrap();
                let full_path = if &*nested_path == "/" {
                    path.to_owned()
                } else {
                    let nested = nested_path.as_ref();
                    let mut joined = String::with_capacity(path.len() + nested.len());
                    let mut path_chars = path.chars();
                    loop {
                        match path_chars.next() {
                            Some(ch) => joined.push(ch),
                            None => break,
                        }
                    }
                    let mut nested_chars = nested.chars();
                    loop {
                        match nested_chars.next() {
                            Some(ch) => joined.push(ch),
                            None => break,
                        }
                    }
                    joined
                };

                match route {
                    Endpoint::MethodRouter(method_router) => {
                        let method_router = method_router.layer(layer_fn({
                            let prefix_bytes = prefix_bytes.clone();
                            move |inner| StripPrefix::new(inner, prefix_bytes.as_str())
                        }));

                        let method_router_to_insert = if let Some(route_id) =
                            self.node.path_to_route_id.get(full_path.as_str()).copied()
                        {
                            match self.routes.get(&route_id) {
                                Some(Endpoint::MethodRouter(prev_method_router)) => {
                                    let merged =
                                        prev_method_router.clone().merge(method_router);
                                    self.routes.insert(
                                        route_id,
                                        Endpoint::MethodRouter(merged),
                                    );
                                    None
                                }
                                _ => Some(method_router),
                            }
                        } else {
                            Some(method_router)
                        };

                        if let Some(method_router) = method_router_to_insert {
                            let route_id = RouteId::next();
                            match self.node.inner.insert(&full_path, route_id) {
                                Ok(()) => {
                                    let shared_path: Arc<str> = full_path.into();
                                    self.node
                                        .route_id_to_path
                                        .insert(route_id, shared_path.clone());
                                    self.node.path_to_route_id.insert(shared_path, route_id);
                                    self.routes.insert(
                                        route_id,
                                        Endpoint::MethodRouter(method_router),
                                    );
                                }
                                Err(err) => {
                                    if self.nested_at_root {
                                        panic!(
                                            "Invalid route: {}. Note that `nest(\"/\", _)` conflicts with all routes. Use `Router::fallback` instead",
                                            err,
                                        );
                                    } else {
                                        panic!("Invalid route: {}", err);
                                    }
                                }
                            }
                        }
                    }
                    Endpoint::Route(route) => {
                        self = self.route(
                            &full_path,
                            StripPrefix::new(route, prefix_bytes.as_str()),
                        );
                    }
                }
            }

            debug_assert!(routes.is_empty());
        } else {
            let svc = svc_holder.unwrap();
            let nested_wildcard_path = if path == "/" {
                let mut wildcard = String::with_capacity(2 + NEST_TAIL_PARAM.len());
                wildcard.push('/');
                wildcard.push('*');
                wildcard.push_str(NEST_TAIL_PARAM);
                wildcard
            } else {
                let mut wildcard = String::with_capacity(path.len() + 2 + NEST_TAIL_PARAM.len());
                let mut path_chars = path.chars();
                loop {
                    match path_chars.next() {
                        Some(ch) => wildcard.push(ch),
                        None => break,
                    }
                }
                wildcard.push('/');
                wildcard.push('*');
                wildcard.push_str(NEST_TAIL_PARAM);
                wildcard
            };

            self = self.route(
                &nested_wildcard_path,
                StripPrefix::new(svc, prefix),
            );
        }

        self
    }

    #[doc = include_str!("../docs/routing/merge.md")]
    pub fn merge(mut self, other: Router<B>) -> Self {
        let Router {
            routes,
            node,
            fallback,
            nested_at_root,
        } = other;

        for (id, route) in routes {
            let path = node
                .route_id_to_path
                .get(&id)
                .expect("no path for route id. This is a bug in axum. Please file an issue");
            self = match route {
                Endpoint::MethodRouter(route) => self.route(path, route),
                Endpoint::Route(route) => self.route(path, route),
            };
        }

        self.fallback = match (self.fallback, fallback) {
            (Fallback::Default(_), pick @ Fallback::Default(_)) => pick,
            (Fallback::Default(_), pick @ Fallback::Custom(_)) => pick,
            (pick @ Fallback::Custom(_), Fallback::Default(_)) => pick,
            (Fallback::Custom(_), Fallback::Custom(_)) => {
                panic!("Cannot merge two `Router`s that both have a fallback")
            }
        };

        self.nested_at_root = self.nested_at_root || nested_at_root;

